'use strict';
/**
 * FE mock server data contributor for the entity set Release (draft root with the scope link table
 * release × process team × business process). Actions: startRegressionRun · refreshRegressionRun · copyScopeFromPredecessor.
 * Behavior in mock-backend/services/ReleaseService.js; initial data: Release.json (generated by the seed).
 */
const releaseService = require('../../../../mock-backend/services/ReleaseService');
const { DRAFT_ACTIONS, addMessages, run, applyDerived, refreshResponse } = require('../../../../mock-backend/services/mockServerAdapter');

const ACTIONS = {
    startRegressionRun: (repo, keys) => releaseService.startRegressionRun(repo, keys),
    refreshRegressionRun: (repo, keys) => releaseService.refreshRegressionRun(repo, keys),
    copyScopeFromPredecessor: (repo, keys) => releaseService.copyScopeFromPredecessor(repo, keys)
};

/** status of the active release before an activation (onBeforeAction → onAfterAction) */
const previousStatus = new WeakMap();

module.exports = {
    async onBeforeAddEntry(keys, data) {
        Object.assign(data, releaseService.initialRelease(data));
    },

    /** feature control of the release actions, always derived from the current state */
    async onAfterRead(data, odataRequest) {
        return applyDerived(data, async (row) => {
            if (!row.ReleaseID || row.IsActiveEntity === undefined) {
                return undefined;
            }
            const stored = (await this.base.fetchEntries({ ReleaseID: row.ReleaseID, IsActiveEntity: row.IsActiveEntity }, odataRequest))[0];
            return stored ? releaseService.deriveRelease(stored) : undefined;
        });
    },

    async onBeforeAction(actionDefinition, actionData, keys, odataRequest) {
        if (actionDefinition.name === 'Activate' && keys?.ReleaseID) {
            const active = (await this.base.fetchEntries({ ReleaseID: keys.ReleaseID, IsActiveEntity: true }, odataRequest))[0];
            previousStatus.set(odataRequest, active ? active.ReleaseStatus : undefined);
        }
        return actionData;
    },

    /** Prepare (Save, step 1): name, dates, scope entries */
    async onDraftPrepare(actionDefinition, responseData, keys, odataRequest) {
        await run(this, odataRequest, (repo) => releaseService.validateRelease(repo, keys.ReleaseID), { boundAction: true });
    },

    async executeAction(actionDefinition, actionData, keys, odataRequest) {
        const action = ACTIONS[actionDefinition.name];
        if (!action) {
            return actionData;
        }
        return run(
            this,
            odataRequest,
            async (repo) => {
                const releaseKeys = { ReleaseID: keys.ReleaseID, IsActiveEntity: keys.IsActiveEntity === true || keys.IsActiveEntity === 'true' };
                const { messages } = await action(repo, releaseKeys);
                await releaseService.syncDerived(repo, releaseKeys.ReleaseID);
                addMessages(odataRequest, messages);
                return repo.findOne('Release', releaseKeys);
            },
            { boundAction: true }
        );
    },

    /** Edit / Activate / Discard: feature control; Activate: value help, read models, automatic regression at test start */
    async onAfterAction(actionDefinition, actionData, keys, responseData, odataRequest) {
        const response = await responseData;
        if (!DRAFT_ACTIONS.has(actionDefinition.name) || !keys?.ReleaseID) {
            return response;
        }
        return run(this, odataRequest, async (repo) => {
            if (actionDefinition.name === 'Activate') {
                const messages = await releaseService.onReleaseActivated(repo, keys.ReleaseID, previousStatus.get(odataRequest));
                previousStatus.delete(odataRequest);
                addMessages(odataRequest, messages);
            }
            await releaseService.syncDerived(repo, keys.ReleaseID);
            if (response?.ReleaseID) {
                refreshResponse(response, await repo.findOne('Release', { ReleaseID: response.ReleaseID, IsActiveEntity: response.IsActiveEntity }));
            }
            return response;
        });
    }
};
